import gurobipy as gp
from gurobipy import GRB
platforms = []
platform_capacity = {}
genres = []
genre_value = {}
genre_requirement = {}
for rec in LEGACY_RECORDS:
    v = rec['values']
    if 'resource_id' in v and 'resource_capacity' in v:
        pid = str(v['resource_id'])
        platforms.append(pid)
        platform_capacity[pid] = int(v['resource_capacity'])
    if 'item_name' in v and 'item_value' in v and ('resource_requirement' in v):
        gname = v['item_name']
        genres.append(gname)
        genre_value[gname] = int(v['item_value'])
        genre_requirement[gname] = int(v['resource_requirement'])
if len(platforms) == 0 or len(genres) == 0:
    raise ValueError('Missing platforms or genres in LEGACY_RECORDS')
for pid in platforms:
    if pid not in platform_capacity:
        raise ValueError(f'Missing capacity for platform {pid}')
for g in genres:
    if g not in genre_value or g not in genre_requirement:
        raise ValueError(f'Missing value or requirement for genre {g}')
m = gp.Model('Game_Store_Listing')
x = m.addVars(platforms, genres, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((genre_value[g] * x[p, g] for p in platforms for g in genres)), GRB.MAXIMIZE)
m.addConstrs((gp.quicksum((genre_requirement[g] * x[p, g] for g in genres)) <= platform_capacity[p] for p in platforms), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')